*** Begin Patch
*** Add File: slides/utils_pptx.js
+// Minimal helpers inspired by the pptx-generator skill guidance.
+
+function clamp(num, min, max) {
+  return Math.max(min, Math.min(max, num));
+}
+
+// Fit image within a box, preserving aspect ratio.
+// PptxGenJS expects x/y/w/h in inches.
+function imageSizingContain(imgW, imgH, x, y, w, h) {
+  if (!imgW || !imgH) return { x, y, w, h };
+  const imgRatio = imgW / imgH;
+  const boxRatio = w / h;
+  if (imgRatio > boxRatio) {
+    const newH = w / imgRatio;
+    return { x, y: y + (h - newH) / 2, w, h: newH };
+  }
+  const newW = h * imgRatio;
+  return { x: x + (w - newW) / 2, y, w: newW, h };
+}
+
+// Conservative shadow helper (PptxGenJS shadow can be finicky across viewers).
+function safeOuterShadow(color, opacity, angle, blur, distance) {
+  return {
+    type: "outer",
+    color,
+    opacity: clamp(opacity, 0, 1),
+    angle: clamp(angle, 0, 359),
+    blur: clamp(blur, 0, 10),
+    distance: clamp(distance, 0, 10),
+  };
+}
+
+function calcTextBoxHeight(fontSizePt, lines, lineHeightMultiple = 1.15, paddingIn = 0.1) {
+  // 72 pt per inch. Approx line height = fontSize * lineHeightMultiple.
+  const lineHIn = (fontSizePt * lineHeightMultiple) / 72;
+  return lines * lineHIn + paddingIn;
+}
+
+module.exports = {
+  imageSizingContain,
+  safeOuterShadow,
+  calcTextBoxHeight,
+};
+
*** End Patch
PATCH

