+const pptxgen = require("pptxgenjs");
+const { theme } = require("./theme");
+const { addFooter, addSource } = require("./utils");
+
+const slideConfig = {
+  type: "cover",
+  index: 1,
+  title: "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks",
+};
+
+function createSlide(pres, t = theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: t.bg };
+
+  // Left color rail
+  slide.addShape(pres.ShapeType.rect, {
+    x: 0,
+    y: 0,
+    w: 0.22,
+    h: 5.625,
+    fill: { color: t.primary },
+    line: { color: t.primary },
+  });
+
+  // Title block
+  slide.addText("Scale SEAL Leaderboards", {
+    x: 0.65,
+    y: 1.4,
+    w: 8.9,
+    h: 0.6,
+    fontFace: t.fontHeader,
+    fontSize: 48,
+    color: t.primary,
+    bold: true,
+  });
+
+  slide.addText("How frontier models stack up across 20+ AI benchmarks", {
+    x: 0.65,
+    y: 2.1,
+    w: 8.9,
+    h: 0.5,
+    fontFace: t.fontBody,
+    fontSize: 22,
+    color: t.secondary,
+    bold: false,
+  });
+
+  // Context chips
+  const chipY = 3.1;
+  const chips = [
+    "100+ models evaluated",
+    "4 capability domains",
+    "Private + public datasets",
+    "Scores include confidence intervals",
+  ];
+  let x = 0.65;
+  for (const text of chips) {
+    const w = Math.max(1.55, text.length * 0.12 + 0.5);
+    slide.addShape(pres.ShapeType.roundRect, {
+      x,
+      y: chipY,
+      w,
+      h: 0.42,
+      fill: { color: t.light, transparency: 20 },
+      line: { color: t.light, transparency: 50 },
+      radius: 0.12,
+    });
+    slide.addText(text, {
+      x,
+      y: chipY + 0.06,
+      w,
+      h: 0.3,
+      fontFace: t.fontBody,
+      fontSize: 14,
+      color: t.primary,
+      bold: false,
+      align: "center",
+      valign: "mid",
+    });
+    x += w + 0.18;
+    if (x > 9.2) break;
+  }
+
+  // Brand context
+  slide.addText("Source: Scale Labs SEAL Leaderboards", {
+    x: 0.65,
+    y: 4.55,
+    w: 8.9,
+    h: 0.3,
+    fontFace: t.fontBody,
+    fontSize: 14,
+    color: t.secondary,
+    bold: false,
+  });
+  addSource(slide, t, "Data: scale.com/leaderboard (as summarized in provided brief)");
+  addFooter(slide, t, 1);
+  return slide;
+}
+
+if (require.main === module) {
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+  createSlide(pres, theme);
+  pres.writeFile({ fileName: "slide-01-preview.pptx" });
+}
